-- 1CORINTHIANS - POR Combined
-- Generated: 2026-01-22T06:20:02.201Z

-- c011-v001: Imitadores meus sede, como também–eu de–Cristo.
-- c011-v002: Louvo porém vos, que em–tudo de–mim vos–lembrais; e como entreguei a–vós, –as tradições retéis.
-- c011-v003: Quero porém vos saber, que de–todo homem –a cabeça, –o Cristo é; cabeça porém de–mulher –o homem; cabeça porém –de Cristo, –o Deus.
-- c011-v004: Todo homem orando ou profetizando, sobre cabeça tendo, desonra –a cabeça sua.
-- c011-v005: Toda porém mulher orando ou profetizando, com–descoberta –a cabeça, desonra –a cabeça sua; uma pois é, e –a mesma, com–a rapada.
-- c011-v006: Se pois não se–cobre mulher, também tosquie–se. Se porém vergonhoso à–mulher –o tosquiar–se ou rapar–se, cubra–se.
-- c011-v007: Homem de–fato pois não deve cobrir –a cabeça, imagem e glória de–Deus sendo; a mulher porém, glória do–homem é.
-- c011-v008: Não pois é homem de mulher, mas mulher de homem.
-- c011-v009: Porque pois não foi–criado homem por–causa–de –a mulher, mas mulher por–causa–de –o homem.
-- c011-v010: Por–isso isto, deve a mulher autoridade ter sobre –a cabeça, por–causa–de –os anjos.
-- c011-v011: Contudo, nem mulher sem homem, nem homem sem mulher, no Senhor.
-- c011-v012: Assim–como pois a mulher, do –o homem; assim também o homem por–meio, –da mulher; –as porém todas–as–coisas, de –o Deus.
-- c011-v013: Em vós mesmos julgai: próprio é à–mulher descoberta, –a Deus orar?
-- c011-v014: Nem –a natureza mesma ensina vos, que homem de–fato se deixa–crescer–o–cabelo, desonra a–ele é?
-- c011-v015: Mulher porém se deixa–crescer–o–cabelo, glória a–ela é; porque –a cabeleira em–lugar–de, véu foi–dada a–ela.
-- c011-v016: Se porém alguém pensa contencioso ser, nós tal costume não temos, nem –as igrejas –de Deus.
-- c011-v017: Isto porém ordenando, não louvo, que não para –o melhor, mas para –o pior, vos–reunis.
-- c011-v018: Primeiro de–fato, pois reunindo–vos vós em igreja, ouço divisões entre vós existirem, e em–parte algo creio.
-- c011-v019: É–necessário pois também heresias entre vós haver, para–que também os aprovados, manifestos se–tornem entre vós.
-- c011-v020: Reunindo–vos portanto vós, em –o mesmo, não é do–Senhor ceia comer.
-- c011-v021: Cada–um pois, –a própria ceia, antecipa no –o comer; e um de–fato tem–fome, outro porém se–embriaga.
-- c011-v022: Não pois casas não tendes, para –o comer e beber? Ou –a igreja –de Deus desprezais, e envergonhais –os não tendo? Que diga a–vós? Louve vos nisto nisto? Não louvo!
-- c011-v023: Eu pois recebi do –o Senhor, o–que também entreguei a–vós: que o Senhor Jesus na –a noite em–que era–traído, tomou pão,
-- c011-v024: e tendo–dado–graças partiu, e disse, Isto meu é –o corpo, –o por vós; isto fazei para –a minha lembrança.
-- c011-v025: Da–mesma–forma também, –o cálice, depois–de –o cear, dizendo, Este –o cálice –a nova aliança é, no –o meu sangue; isto fazei, tantas–vezes–quantas se beberdes, para –a minha lembrança.
-- c011-v026: Tantas–vezes–quantas pois, se comerdes –o pão este, e –o cálice beberdes, –a morte –do Senhor anunciais, até–que que venha.
-- c011-v027: De–modo–que quem porventura comer –o pão, ou beber –o cálice –do Senhor indignamente, culpado será –do corpo, e –do sangue –do Senhor.
-- c011-v028: Examine–se porém o–homem a–si–mesmo, e assim do –o pão coma, e do –o cálice beba.
-- c011-v029: O pois comendo e bebendo juízo para–si–mesmo, come e bebe, não discernindo –o corpo.
-- c011-v030: Por–isso isto, entre vós muitos fracos e doentes, e dormem muitos.
-- c011-v031: Se porém a–nós–mesmos julgássemos, não porventura seríamos–julgados.
-- c011-v032: Sendo–julgados porém pelo –o Senhor, somos–disciplinados, para–que não com –o mundo sejamos–condenados.
-- c011-v033: De–modo–que, irmãos meus, reunindo–vos para –o comer, uns–aos–outros esperai.
-- c011-v034: Se alguém tem–fome, em casa coma, para–que não para juízo vos–reuníeis; –as porém demais–coisas, quando porventura vier, ordenarei.

